# Unit 6 Parsons authoring, part A: 6.1 Setting up Bootstrap, 6.2 The grid, 6.3 Typography, colors and buttons
# P(title, story, lines, dis, mode, css) ; mode "head": the lines are a whole page start (head + first body line); "body": the lines are the body
def P(title, story, lines, dis, mode='body', css=None, pre='', post=''): return dict(title=title, story=story, lines=lines, dis=dis, mode=mode, css=css, pre=pre, post=post)
BS = '<link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.9/dist/css/bootstrap.min.css" rel="stylesheet">'
BSF = '<link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.9/dist/css/bootstrap.min.css" rel="stylesheet" integrity="sha384-yEPZ7jP9S0QKiUQ0m3jjsO4ProIW7wvR9gXkI7JOGa2XVsw53Yke2bsdkBbjmmiX" crossorigin="anonymous">'
OWN = '<link rel="stylesheet" href="style.css">'
def bad(s, a, b): return s.replace(a, b)
def head(title, *mid, body=()): return ['<head>', '<title>%s</title>' % title] + list(mid) + ['</head>', '<body>'] + list(body)
